    state.drag = null;
  }
  refreshAll();
});
window.addEventListener("mousemove", e => {
  if (!state.drag) return;
  const [mx, my] = mousePos(e);
  const d = state.drag;
  if (mx === d.mx && my === d.my && !d.mutated) return;
  if (!d.mutated) {
    const w = win();
    w.undo.push(d.preBytes);
    if (w.undo.length > 100) w.undo.shift();
    d.mutated = true;
  }
  const f = win().swd.fields[d.i];
  if (d.resize) {
    if (d.nearRight) f.lx = Math.max(2, d.olx + mx - d.mx);
    if (d.nearBottom) f.ly = Math.max(2, d.oly + my - d.my);
  } else {
    f.x = d.ox + mx - d.mx;
    f.y = d.oy + my - d.my;
  }
  win().dirty = true;
  render();
  status(`${f.name || f.typeName}: x=${f.x} y=${f.y} ${f.lx}×${f.ly}`);
});
window.addEventListener("mouseup", () => {
  if (state.drag) { state.drag = null; refreshAll(); }
});
window.addEventListener("keydown", e => {
  const w = win();
  if (!w || state.curFld < 0 || e.target.tagName === "INPUT" || e.target.tagName === "SELECT") return;
  const f = w.swd.fields[state.curFld];
  const step = e.shiftKey ? 8 : 1;
  let moved = true;
  if (!e.repeat && e.key.startsWith("Arrow")) snapshot(); // one undo entry per press-and-hold
  if (e.key === "ArrowLeft") f.x -= step;
  else if (e.key === "ArrowRight") f.x += step;
  else if (e.key === "ArrowUp") f.y -= step;
  else if (e.key === "ArrowDown") f.y += step;
  else moved = false;
  if (moved) { w.dirty = true; refreshAll(); e.preventDefault(); }
});

// ---------- field / window commands ----------
$("addFldBtn").onclick = () => {
  const w = win();
  snapshot();
  state.curFld = addField(w.swd, { name: "NEWFIELD", label: "NEW" });
  markDirty();
};
$("dupFldBtn").onclick = () => {
  const w = win();
  snapshot();
  const src = w.swd.fields[state.curFld];
  state.curFld = addField(w.swd, { cloneFrom: state.curFld, name: src.name, label: src.textResolved ?? "", y: src.y + src.ly + 2 });
  markDirty();
};
$("delFldBtn").onclick = () => {
  const w = win();
  snapshot();
  deleteField(w.swd, state.curFld);
  state.curFld = -1;
  markDirty();
};
$("newWinBtn").onclick = () => {
  const name = prompt("Window item name (…_SWD, max 15 ASCII chars):", "CUSTOM_SWD");
  if (!name || !state.glbs) return;
  // discovery is a case-sensitive /_SWD$/ match, and engine name lookup
  // resolves the FIRST item with a name - enforce both up front
  if (!/^[A-Z0-9_]{1,11}_SWD$/.test(name)) {
    status(`⚠ name must be UPPERCASE, end in _SWD, max 15 chars: ${name}`);
    return;
  }
  if (state.glbs.itemId(name) !== -1) {
    status(`⚠ an item named ${name} already exists`);
    return;
  }
  if (state.windows.some(w => w.name === name)) {
    status(`⚠ a window named ${name} already exists`);
    return;
  }
  const nums = state.glbs.nums();
  const num = nums.includes(1) ? 1 : nums[0];
  let swd;
  try {
    swd = newWindow({ name });
  } catch (e) {
    status(`⚠ ${e.message}`);
    return;
  }
  // index -1 = not yet in the archive; the item is only appended at export,
  // so discarding unsaved work really discards it
  state.windows.push({ num, index: -1, name, swd, dirty: true, undo: [] });
  state.cur = state.windows.length - 1;
  state.curFld = -1;
  refreshAll();
};

$("zoomSel").onchange = e => { state.zoom = +e.target.value; render(); };

function refreshAll() { refreshLists(); refreshProps(); render(); }
</script>
