  "final_artifact": "# === build.mjs ===\n// Bundles index.html + src modules into a single self-contained HTML file:\n// dist/raptor-window-maker.html. No dependencies - the modules deliberately\n// avoid name collisions, so bundling is import/export stripping plus\n// concatenation in dependency order.\n\nimport { readFileSync, writeFileSync, mkdirSync } from \"node:fs\";\nimport { dirname, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst ROOT = dirname(fileURLToPath(import.meta.url));\nconst ORDER = [\"src/glb.mjs\", \"src/swd.mjs\", \"src/gfx.mjs\", \"src/glbset.mjs\", \"src/render.mjs\", \"src/edit.mjs\"];\n\nfunction strip(source) {\n  return source\n    .replace(/^import\\s*\\{[^}]*\\}\\s*from\\s*\"[^\"]*\";\\s*$/gm, \"\")\n    .replace(/^import\\s+[\\w$]+\\s+from\\s*\"[^\"]*\";\\s*$/gm, \"\")\n    .replace(/^export\\s+/gm, \"\");\n}\n\nconst modules = ORDER.map(p => `// ==== ${p} ====\\n${strip(readFileSync(join(ROOT, p), \"utf8\"))}`).join(\"\\n\");\nconst html = readFileSync(join(ROOT, \"index.html\"), \"utf8\");\n\n// import-stripping sanity: no import statements may survive into the bundle\nconst leftover = modules.match(/^\\s*import\\b.*$/m);\nif (leftover) throw new Error(`unstripped import in bundle: ${leftover[0].trim()}`);\n\nconst out = html.replace(\n  /<script type=\"module\">([\\s\\S]*?)<\\/script>/,\n  (_, app) => `<script type=\"module\">\\n${modules}\\n${strip(app)}</script>`,\n);\nif (out === html) throw new Error(\"app <script type=\\\"module\\\"> block not found\");\n\nmkdirSync(join(ROOT, \"dist\"), { recursive: true });\nwriteFileSync(join(ROOT, \"dist\", \"raptor-window-maker.html\"), out);\nconsole.log(`dist/raptor-window-maker.html (${(out.length / 1024).toFixed(0)} KB)`);\n\n\n# === FORMAT.md ===\n# SWD window resource format\n\nThe menus and dialogs of Raptor: Call of the Shadows (1994) are data-driven:\neach window is a `*_SWD` item inside the game's GLB archives, produced by\nScott Host's original \"window maker\" tool (source lost). This documents the\non-disk format, recovered from three independent sources that all agree:\n\n1. `swdapi.h` in the open-source engine port — the `SWIN` and `SFIELD32`\n   struct definitions (the disk layout, including the `PlaceHolder` member\n   that pads the field record to its 32-bit size).\n2. `swdapi.cpp` — the code that loads and draws these resources, which pins\n   down the semantics (notably text offset resolution).\n3. The Delta Sector installer's working binary patch of `SHIPCOMP_SWD`.\n\nValidation: `tests/roundtrip.test.mjs` parses and re-serializes **every SWD\nitem in the shipped full game (16 windows, 148 fields) byte-identically**,\nagainst both the 1994 v1.2 data and a Delta-patched copy. The 2015 Edition\nuses byte-identical data files, so everything here applies to it unchanged.\n\n## Layout\n\n```\nSWIN header        120 bytes\n(gap)              optional unused bytes up to header.fldofs (none in shipped data)\nSFIELD32 records   148 bytes x header.numflds, starting at header.fldofs\ntext area          everything after the last field record\n```\n\nAll integers are little-endian signed 32-bit. Strings are NUL-terminated\nASCII in fixed 16-byte arrays (bytes after the NUL are preserved as-is by\nthis library, since shipped items carry residue there).\n\n## SWIN header (120 bytes)\n\n| offset | field      | notes                                          |\n|-------:|------------|------------------------------------------------|\n|      0 | version    | unused                                         |\n|      4 | swdsize    | unused                                         |\n|      8 | arrowflag  | arrow keys navigate fields (bool)              |\n|     12 | display    | display flag                                   |\n|     16 | opt3       | unused                                         |\n|     20 | opt4       | unused                                         |\n|     24 | id         | window id                                      |\n|     28 | type       | window type                                    |\n|     32 | name[16]   | window name (not displayed)                    |\n|     48 | item_name[16] | background art item name                    |\n|     64 | item       | background art item id                         |\n|     68 | picflag    | 0 fill / 1 texture / 2 picture / 3 see-thru / 4 invisible |\n|     72 | lock       | true = cannot switch to other windows          |\n|     76 | fldofs     | byte offset of first field record              |\n|     80 | txtofs     | byte offset of text area (unused by engine)    |\n|     84 | firstfld   | field to focus first                           |\n|     88 | opt        | window type option                             |\n|     92 | color      | window color                                   |\n|     96 | numflds    | number of field records                        |\n|    100 | x, y       | screen position (320x200 space)                |\n|    108 | lx, ly     | width, height in pixels                        |\n|    116 | shadow     | drop shadow (bool)                             |\n\n## SFIELD32 record (148 bytes)\n\n| offset | field         | notes                                       |\n|-------:|---------------|---------------------------------------------|\n|      0 | opt           | field type (table below)                    |\n|      4 | id            | field id (what the game code switches on)   |\n|      8 | hotkey        | keyboard scan code                          |\n|     12 | kbflag        | keyboard-active (bool)                      |\n|     16 | opt3, opt4    | unused                                      |\n|     24 | input_opt     | input fields: 0 normal / 1 toupper / 2 numeric |\n|     28 | bstatus       | button state: 0 normal / 1 up / 2 down      |\n|     32 | name[16]      | field name (not displayed; e.g. `GAME4`)    |\n|     48 | item_name[16] | art item name                               |\n|     64 | item          | art item id                                 |\n|     68 | font_name[16] | font GLB item name                          |\n|     84 | fontid        | font number                                 |\n|     88 | fontbasecolor | font base color                             |\n|     92 | maxchars      | max chars of field text                     |\n|     96 | picflag       | picture (bool)                              |\n|    100 | color         | field color                                 |\n|    104 | lite          | highlight color                             |\n|    108 | mark          | field mark (bool)                           |\n|    112 | saveflag      | save background under field (bool)          |\n|    116 | shadow        | shadow (bool)                               |\n|    120 | selectable    | selectable (bool)                           |\n|    124 | x, y          | position, relative to window origin         |\n|    132 | lx, ly        | width, height in pixels                     |\n|    140 | txtoff        | text offset, **relative to this record's own start** (`swdapi.cpp:329`) |\n|    144 | placeholder   | pads record to in-memory struct size        |\n\n## Field types\n\nCounts are from the pristine 1994 v1.2 full game (16 windows, 148 fields).\n\n| opt | type     | shipped count |\n|----:|----------|--------------:|\n|   0 | off      | 0 |\n|   1 | text     | 30 |\n|   2 | button   | 41 |\n|   3 | input    | 2 |\n|   4 | mark     | 0 |\n|   5 | close    | 4 |\n|   6 | dragbar  | 3 |\n|   7 | bumpin   | 11 |\n|   8 | bumpout  | 10 |\n|   9 | icon     | 27 |\n|  10 | objarea  | 0 |\n|  11 | viewarea | 20 |\n\n## Editing gotcha\n\nBecause `txtoff` is relative to each field's record start, inserting a field\nrecord shifts the text area away from every existing record: all prior\nfields' `txtoff` values must grow by 148 per inserted field (this is exactly\nwhat the Delta Sector installer does when adding the GAME4 button).\n\n\n# === index.html ===\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Raptor Window Maker</title>\n<style>\n  :root { --bg:#15181d; --panel:#1d2128; --edge:#2c323c; --fg:#cdd3dd; --dim:#8a93a2; --acc:#e8a33d; }\n  * { box-sizing: border-box; }\n  body { margin:0; background:var(--bg); color:var(--fg); font:13px/1.45 system-ui, sans-serif; height:100vh; display:flex; flex-direction:column; }\n  header { display:flex; align-items:center; gap:12px; padding:6px 12px; background:var(--panel); border-bottom:1px solid var(--edge); }\n  header h1 { font-size:14px; margin:0; color:var(--acc); }\n  header .spacer { flex:1; }\n  main { flex:1; display:flex; min-height:0; }\n  #sidebar { width:200px; background:var(--panel); border-right:1px solid var(--edge); overflow-y:auto; padding:8px; }\n  #sidebar h2, #props h2 { font-size:11px; text-transform:uppercase; letter-spacing:.08em; color:var(--dim); margin:10px 0 4px; }\n  .winrow, .fldrow { padding:3px 6px; border-radius:4px; cursor:pointer; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n  .winrow:hover, .fldrow:hover { background:#262c36; }\n  .winrow.sel, .fldrow.sel { background:#33415c; color:#fff; }\n  .winrow .dirty { color:var(--acc); }\n  #center { flex:1; display:flex; flex-direction:column; min-width:0; }\n  #canvasWrap { flex:1; overflow:auto; display:grid; place-items:center; background:#0d0f12; }\n  canvas { image-rendering: pixelated; }\n  #statusbar { padding:3px 12px; font-size:12px; color:var(--dim); background:var(--panel); border-top:1px solid var(--edge); min-height:22px; }\n  #props { width:270px; background:var(--panel); border-left:1px solid var(--edge); overflow-y:auto; padding:8px 10px; }\n  #props label { display:flex; align-items:center; justify-content:space-between; gap:6px; margin:3px 0; color:var(--dim); }\n  #props input[type=text], #props input[type=number], #props select {\n    width:140px; background:#12151a; color:var(--fg); border:1px solid var(--edge); border-radius:4px; padding:2px 5px; font:12px monospace; }\n  #props input[type=checkbox] { accent-color: var(--acc); }\n  button { background:#2a313d; color:var(--fg); border:1px solid var(--edge); border-radius:5px; padding:3px 10px; cursor:pointer; font-size:12px; }\n  button:hover { background:#333c4b; }\n  button.warn { color:#e88; }\n  .swatch { display:inline-block; width:16px; height:16px; border:1px solid #000; vertical-align:middle; cursor:pointer; border-radius:3px; }\n  #palPop { position:fixed; background:var(--panel); border:1px solid var(--edge); padding:6px; border-radius:6px; box-shadow:0 6px 24px #000a; z-index:10; }\n  #palPop canvas { image-rendering:pixelated; cursor:crosshair; }\n  #dropHint { padding:30px; text-align:center; color:var(--dim); }\n  #dropHint b { color:var(--fg); }\n  a { color:var(--acc); }\n</style>\n</head>\n<body>\n<header>\n  <h1>Raptor Window Maker</h1>\n  <input type=\"file\" id=\"fileInput\" multiple accept=\".glb,.GLB\" style=\"display:none\">\n  <button id=\"openBtn\">Open GLB files…</button>\n  <label style=\"color:var(--dim)\">Zoom\n    <select id=\"zoomSel\"><option>2</option><option selected>3</option><option>4</option></select>\n  </label>\n  <div class=\"spacer\"></div>\n  <span id=\"exportSlot\"></span>\n</header>\n<main>\n  <div id=\"sidebar\">\n    <h2>Windows</h2>\n    <div id=\"winList\"></div>\n    <div style=\"margin-top:6px\"><button id=\"newWinBtn\" disabled>New window…</button></div>\n    <h2>Fields</h2>\n    <div id=\"fldList\"></div>\n    <div style=\"margin-top:6px; display:flex; gap:6px; flex-wrap:wrap\">\n      <button id=\"addFldBtn\" disabled>Add</button>\n      <button id=\"dupFldBtn\" disabled>Clone</button>\n      <button id=\"delFldBtn\" disabled class=\"warn\">Delete</button>\n    </div>\n  </div>\n  <div id=\"center\">\n    <div id=\"canvasWrap\">\n      <div id=\"dropHint\"><b>Drop your Raptor GLB files here</b><br>\n        (FILE0000.GLB … FILE0004.GLB — at minimum FILE0000 for the palette<br>\n        and FILE0001 for the windows, fonts and art)<br><br>\n        Everything runs locally; your files never leave this machine.</div>\n      <canvas id=\"view\" style=\"display:none\"></canvas>\n    </div>\n    <div id=\"statusbar\">No files loaded.</div>\n  </div>\n  <div id=\"props\"></div>\n</main>\n<script type=\"module\">\nimport { GlbSet } from \"./src/glbset.mjs\";\nimport { parseSwd, serializeSwd, FIELD_TYPES, DRAW_STYLES } from \"./src/swd.mjs\";\nimport { RenderContext, drawWindow } from \"./src/render.mjs\";\nimport { setLabel, addField, deleteField, setProps, compactText, newWindow } from \"./src/edit.mjs\";\nimport { SCREEN_W, SCREEN_H } from \"./src/gfx.mjs\";\n\nconst $ = id => document.getElementById(id);\nconst state = {\n  glbs: null, ctx: null,\n  windows: [],          // { num, index, name, swd, dirty, undo: [] }\n  cur: -1, curFld: -1,\n  zoom: 3,\n  drag: null,\n};\n\n// ---------- loading ----------\nasync function loadFiles(files) {\n  if (state.windows.some(w => w.dirty)\n      && !confirm(\"You have unsaved edits. Loading files rebuilds the window list and discards them. Continue?\"))\n    return;\n  state.glbs ??= new GlbSet(); // repeated loads merge/replace by file number\n  let auto = 0;\n  for (const f of files) {\n    const m = f.name.match(/^file(\\d{4})\\.glb$/i);\n    const num = m ? parseInt(m[1], 10) : auto++;\n    try {\n      state.glbs.add(num, new Uint8Array(await f.arrayBuffer()));\n    } catch (e) {\n      status(`⚠ ${f.name}: ${e.message}`);\n      return;\n    }\n  }\n  try {\n    state.ctx = new RenderContext(state.glbs);\n  } catch (e) {\n    status(`⚠ ${e.message} — load FILE0000.GLB too.`);\n    return;\n  }\n  state.windows = [];\n  for (const { num, index, item } of state.glbs.itemsMatching(/_SWD$/)) {\n    try {\n      state.windows.push({ num, index, name: item.name, swd: parseSwd(item.data), dirty: false, undo: [] });\n    } catch (e) {\n      console.warn(`skipping ${item.name}: ${e.messag