rn; }\n  let raster;\n  try {\n    raster = drawWindow(state.ctx, w.swd);\n  } catch (e) {\n    status(`⚠ render error: ${e.message}`);\n    return;\n  }\n  off.getContext(\"2d\").putImageData(new ImageData(raster.toRGBA(state.ctx.rgb), SCREEN_W, SCREEN_H), 0, 0);\n  g.drawImage(off, 0, 0, cv.width, cv.height);\n  // selection overlay\n  const f = w.swd.fields[state.curFld];\n  if (f) {\n    g.strokeStyle = \"#ffd75e\"; g.lineWidth = 1.5; g.setLineDash([4, 3]);\n    g.strokeRect((w.swd.header.x + f.x) * z - 1, (w.swd.header.y + f.y) * z - 1, f.lx * z + 2, f.ly * z + 2);\n    g.setLineDash([]);\n  }\n}\n\n// ---------- lists ----------\nfunction refreshLists() {\n  $(\"winList\").innerHTML = \"\";\n  state.windows.forEach((w, i) => {\n    const d = document.createElement(\"div\");\n    d.className = \"winrow\" + (i === state.cur ? \" sel\" : \"\");\n    d.append(document.createTextNode(w.name)); // archive-controlled: never innerHTML\n    if (w.dirty) {\n      const dot = document.createElement(\"span\");\n      dot.className = \"dirty\";\n      dot.textContent = \" ●\";\n      d.append(dot);\n    }\n    d.onclick = () => { state.cur = i; state.curFld = -1; refreshAll(); };\n    $(\"winList\").append(d);\n  });\n  $(\"fldList\").innerHTML = \"\";\n  const w = win();\n  if (w) w.swd.fields.forEach((f, i) => {\n    const d = document.createElement(\"div\");\n    d.className = \"fldrow\" + (i === state.curFld ? \" sel\" : \"\");\n    const label = f.textResolved ? ` “${f.textResolved}”` : \"\";\n    d.textContent = `${i}: ${f.typeName}${f.name ? \" \" + f.name : \"\"}${label}`;\n    d.onclick = () => { state.curFld = i; refreshAll(); };\n    $(\"fldList\").append(d);\n  });\n  $(\"addFldBtn\").disabled = !w;\n  $(\"dupFldBtn\").disabled = !w || state.curFld < 0;\n  $(\"delFldBtn\").disabled = !w || state.curFld < 0;\n  refreshExport();\n}\n\nfunction refreshExport() {\n  const slot = $(\"exportSlot\");\n  slot.innerHTML = \"\";\n  if (!state.glbs) return;\n  const dirty