rap\">\n      <div id=\"dropHint\"><b>Drop your Raptor GLB files here</b><br>\n        (FILE0000.GLB … FILE0004.GLB — at minimum FILE0000 for the palette<br>\n        and FILE0001 for the windows, fonts and art)<br><br>\n        Everything runs locally; your files never leave this machine.</div>\n      <canvas id=\"view\" style=\"display:none\"></canvas>\n    </div>\n    <div id=\"statusbar\">No files loaded.</div>\n  </div>\n  <div id=\"props\"></div>\n</main>\n<script type=\"module\">\nimport { GlbSet } from \"./src/glbset.mjs\";\nimport { parseSwd, serializeSwd, FIELD_TYPES, DRAW_STYLES } from \"./src/swd.mjs\";\nimport { RenderContext, drawWindow } from \"./src/render.mjs\";\nimport { setLabel, addField, deleteField, setProps, compactText, newWindow } from \"./src/edit.mjs\";\nimport { SCREEN_W, SCREEN_H } from \"./src/gfx.mjs\";\n\nconst $ = id => document.getElementById(id);\nconst state = {\n  glbs: null, ctx: null,\n  windows: [],          // { num, index, name, swd, dirty, undo: [] }\n  cur: -1, curFld: -1,\n  zoom: 3,\n  drag: null,\n};\n\n// ---------- loading ----------\nasync function loadFiles(files) {\n  if (state.windows.some(w => w.dirty)\n      && !confirm(\"You have unsaved edits. Loading files rebuilds the window list and discards them. Continue?\"))\n    return;\n  // stage everything; commit to state only after the whole load succeeds,\n  // so a bad file can never leave windows attached to a half-replaced set\n  const glbs = new GlbSet();\n  if (state.glbs) // repeated loads merge/replace by file number\n    for (const num of state.glbs.nums()) glbs.files.set(num, state.glbs.files.get(num));\n  let auto = 0, ctx, windows = [];\n  try {\n    for (const f of files) {\n      const m = f.name.match(/^file(\\d{4})\\.glb$/i);\n      const num = m ? parseInt(m[1], 10) : auto++;\n      glbs.add(num, new Uint8Array(await f.arrayBuffer()));\n    }\n    ctx = new RenderContext(glbs);\n    for (const { num, index, item } of glbs.itemsMatching(/_SWD$/)) {\