// Editing operations on parsed SWD windows (see swd.mjs for the model).
//
// Ops are append-style, matching how the Delta Sector installer patches
// windows: label edits append a new string to the text area and repoint the
// field's txtoff, leaving all other bytes untouched (dead bytes are legal -
// the engine only ever follows txtoff). compactText() garbage-collects.
//
// txtoff bookkeeping: each field's txtoff is relative to its own 148-byte
// record, so inserting/removing a record shifts the text area relative to
// records that DON'T move (the earlier ones) and not relative to ones that
// do. header.txtofs always tracks the text area's absolute offset.

import { SWIN_SIZE, SFIELD32_SIZE, FIELD_TYPES } from "./swd.mjs";

const enc = new TextEncoder();

function fldofs(swd) {
  return SWIN_SIZE + swd.headerGap.length;
}

function textStart(swd) {
  return fldofs(swd) + swd.fields.length * SFIELD32_SIZE;
}

function name16(str) {
  // the format stores NUL-terminated ASCII in 16 bytes (15 usable)
  if (!/^[\x20-\x7e]*$/.test(str)) throw new Error(`name must be ASCII: ${JSON.stringify(str)}`);
  if (str.length > 15) throw new Error(`name too long (max 15 chars): ${str}`);
  const raw = new Uint8Array(16);
  raw.set(enc.encode(str));
  return raw;
}

// Labels are stored as NUL-terminated single-byte ASCII; reject anything
// that would serialize to different bytes than it parses back to.
function checkLabel(str) {
  if (!/^[\x20-\x7e]*$/.test(str))
    throw new Error(`label must be printable ASCII: ${JSON.stringify(str)}`);
}

function checkIndex(swd, index) {
  if (!Number.isInteger(index) || index < 0 || index >= swd.fields.length)
    throw new Error(`no field ${index} (window has ${swd.fields.length})`);
}

function appendText(swd, str) {
  const bytes = enc.encode(str + "\0");
  const pos = swd.text.length;
  const next = new Uint8Array(pos + bytes.length);
  next.set(swd.text);
  next.set(bytes, pos);
  swd.text = next;
  return pos; // offset of the new string within the text area
}

const NAME_KEYS = new Set(["name", "item_name", "font_name"]);

const HEADER_KEYS = new Set([
  "version", "swdsize", "arrowflag", "display", "opt3", "opt4", "id", "type",
  "name", "item_name", "item", "picflag", "lock", "fldofs", "txtofs",
  "firstfld", "opt", "color", "numflds", "x", "y", "lx", "ly", "shadow",
]);
const FIELD_KEYS = new Set([
  "opt", "id", "hotkey", "kbflag", "opt3", "opt4", "input_opt", "bstatus",
  "name", "item_name", "item", "font_name", "fontid", "fontbasecolor",
  "maxchars", "picflag", "color", "lite", "mark", "saveflag", "shadow",
  "selectable", "x", "y", "lx", "ly", "txtoff", "placeholder",
]);

// Assign plain int members and/or the 16-byte name strings on a field or on
// swd.header. The whole patch is validated before anything is assigned, so
// a bad value can never leave the record half-updated.
export function setProps(rec, patch) {
  const isField = "txtoff" in rec;
  const allowed = isField ? FIELD_KEYS : HEADER_KEYS;
  const staged = [];
  for (const [k, v] of Object.entries(patch)) {
    if (!allowed.has(k)) throw new Error(`unknown ${isField ? "field" : "window"} property: ${k}`);
    staged.push(NAME_KEYS.has(k) ? [k, v, name16(v)] : [k, v | 0, null]);
  }
  for (const [k, v, raw] of staged) {
    if (raw) {
      rec[`${k}Raw`] = raw;
      rec[k] = v;
    } else {
      rec[k] = v;
      if (k === "opt" && isField)
        rec.typeName = FIELD_TYPES[rec.opt] ?? `unknown(${rec.opt})`;
    }
  }
}

export function setLabel(swd, index, label) {
  checkIndex(swd, index);
  checkLabel(label);
  const fld = swd.fields[index];
  const pos = appendText(swd, label);
  fld.txtoff = (textStart(swd) + pos) - (fldofs(swd) + index * SFIELD32_SIZE);
  fld.textResolved = label;
}

// Clone an existing field (or pass a full record) and append it.
// Returns the new field's index.
export function addField(swd, { cloneFrom = null, name, label = "", ...overrides }) {
  // validate everything BEFORE mutating, so a bad argument can't leave the
  // window half-edited (txtoffs shifted, no field appended)
  if (cloneFrom !== null) checkIndex(swd, cloneFrom);
  checkLabel(label);
  if (name !== undefined) name16(name);
  for (const k of Object.keys(overrides)) if (NAME_KEYS.has(k)) name16(overrides[k]);

  for (const f of swd.fields) f.txtoff += SFIELD32_SIZE; // text moves away
  const src = cloneFrom !== null ? swd.fields[cloneFrom] : defaultButton();
  const fld = { ...src, nameRaw: src.nameRaw.slice(), item_nameRaw: src.item_nameRaw.slice(), font_nameRaw: src.font_nameRaw.slice() };
  if (name !== undefined) setProps(fld, { name });
  swd.fields.push(fld);
  const index = swd.fields.length - 1;
  const pos = appendText(swd, label);
  fld.txtoff = (textStart(swd) + pos) - (fldofs(swd) + index * SFIELD32_SIZE);
  fld.textResolved = label;
  setProps(fld, overrides);
  swd.header.numflds = swd.fields.length;
  swd.header.txtofs = textStart(swd);
  return index;
}

export function deleteField(swd, index) {
  checkIndex(swd, index);
  swd.fields.splice(index, 1);
  // records at < index keep their position while the text area moves closer;
  // records after index shift down with the text area, staying relative
  for (let i = 0; i < index; i++) swd.fields[i].txtoff -= SFIELD32_SIZE;
  swd.header.numflds = swd.fields.length;
  swd.header.txtofs = textStart(swd);
}

// Rebuild the text area from the fields' current labels, dropping dead bytes.
export function compactText(swd) {
  // validate and lay out everything before touching the window
  const labels = swd.fields.map(f => f.textResolved ?? "");
  labels.forEach(checkLabel);
  const base = textStart(swd);
  const chunks = [];
  const offsets = [];
  let pos = 0;
  labels.forEach((label, i) => {
    offsets.push((base + pos) - (fldofs(swd) + i * SFIELD32_SIZE));
    const bytes = enc.encode(label + "\0");
    chunks.push(bytes);
    pos += bytes.length;
  });
  const next = new Uint8Array(pos);
  let o = 0;
  for (const c of chunks) { next.set(c, o); o += c.length; }
  swd.fields.forEach((fld, i) => { fld.txtoff = offsets[i]; });
  swd.text = next;
  swd.header.txtofs = base;
}

function defaultButton() {
  return {
    opt: FIELD_TYPES.indexOf("button"), id: 0, hotkey: 0, kbflag: 0,
    opt3: 0, opt4: 0, input_opt: 0, bstatus: 0,
    name: "NEWFIELD", nameRaw: name16("NEWFIELD"),
    item_name: "", item_nameRaw: new Uint8Array(16),
    item: -1,
    font_name: "SYSTEM_FNT", font_nameRaw: name16("SYSTEM_FNT"),
    fontid: -1, fontbasecolor: 16, maxchars: 32, picflag: 0,
    color: 24, lite: 28, mark: 0, saveflag: 0, shadow: 0, selectable: 1,
    x: 8, y: 8, lx: 80, ly: 14, txtoff: 0, placeholder: 0,
    typeName: "button", textResolved: "",
  };
}

// A minimal new fill-style window, ready for addField().
export function newWindow({ name, x = 60, y = 40, lx = 200, ly = 120, color = 24 }) {
  return {
    header: {
      version: 0, swdsize: 0, arrowflag: 1, display: 1, opt3: 0, opt4: 0,
      id: 0, type: 0,
      name, nameRaw: name16(name),
      item_name: "", item_nameRaw: new Uint8Array(16),
      item: -1, picflag: 0, lock: 0, fldofs: SWIN_SIZE, txtofs: SWIN_SIZE,
      firstfld: 0, opt: 0, color, numflds: 0,
      x, y, lx, ly, shadow: 1,
    },
    headerGap: new Uint8Array(0),
    fields: [],
    text: new Uint8Array(0),
  };
}


# === src\gfx.mjs ===
// Pixel-faithful port of the engine's drawing primitives (gfxapi.cpp) to a
// 320x200 indexed framebuffer. Browser-portable: no Node APIs.

export const SCREEN_W = 320;
export const SCREEN_H = 200;

// PALETTE_DAT: 256 x 3 bytes of 6-bit VGA values.
export function parsePalette(raw) {
  if (raw.length < 768) throw new Error(`palette too small (${raw.length} bytes, need 768)`);
  const pal = new Array(256);
  for (let i = 0; i < 256; i++) pal[i] = [raw[i * 3], raw[i * 3 + 1], raw[i * 3 + 2]];
  return pal; // 6-bit components (0-63)
}

export function paletteToRgb(pal6) {
  return pal6.map(([r, g, b]) => [r << 2, g << 2, b << 2]);
}

// GFX_Remap: nearest palette entry by abs-sum distance; ties keep the LAST
// (highest) index, because the original scans 0..255 with `num <= low`.
function remap(pal6, r, g, b) {
  let low = 0x7fffffff, pos = 0;
  for (let i = 0; i < 256; i++) {
    const [pr, pg, pb] = pal6[i];
    const num = Math.abs(pr - r) + Math.abs(pg - g) + Math.abs(pb - b);
    if (num <= low) { low = num; pos = i; }
  }
  return pos;
}

// GFX_MakeLightTable: level is -63..+63 in 6-bit space.
export function makeLightTable(pal6, level) {
  const t = new Uint8Array(256);
  for (let i = 0; i < 256; i++) {
    let [r, g, b] = pal6[i];
    r += level; g += level; b += level;
    if (level >= 0) { r = Math.min(r, 63); g = Math.min(g, 63); b = Math.min(b, 63); }
    else { r = Math.max(r, 0); g = Math.max(g, 0); b = Math.max(b, 0); }
    t[i] = remap(pal6, r, g, b);
  }
  return t;
}

export function makeGreyTable(pal6) {
  const t = new Uint8Array(256);
  for (let i = 0; i < 256; i++) {
    const [r, g, b] = pal6[i];
    const c = Math.floor((r + g + b) / 3);
    t[i] = remap(pal6, c, c, c);
  }
  return t;
}

// GFX_PIC items: GPIC raw 8bpp, GSPRITE opaque segment runs.
export const GTYPE_SPRITE = 0;
export const GTYPE_PIC = 1;

export function parsePic(data) {
  if (data.length < 20) throw new Error(`pic too small (${data.length} bytes)`);
  const dv = new DataView(data.buffer, data.byteOffset);
  const type = dv.getInt32(0, true);
  const w = dv.getInt32(12, true);
  const h = dv.getInt32(16, true);
  if (w < 1 || h < 1 || w > 2048 || h > 2048)
    throw new Error(`implausible pic dimensions ${w}x${h}`);
  if (type === GTYPE_PIC) {
    if (data.length < 20 + w * h)
      throw new Error(`GPIC truncated: ${data.length} bytes for ${w}x${h}`);
    return { type, w, h, pixels: data.slice(20, 20 + w * h), mask: null };
  }
  if (type === GTYPE_SPRITE) {
    const pixels = new Uint8Array(w * h);
    const mask = new Uint8Array(w * h);
    let pos = 20;
    let terminated = false;
    while (pos + 16 <= data.length) {
      const x = dv.getInt32(pos, true);
      const y = dv.getInt32(pos + 4, true);
      const offset = dv.getInt32(pos + 8, true);
      const length = dv.getInt32(pos + 12, true);
      if (offset === -1) { terminated = true; break; }
      pos += 16;
      if (length < 0 || pos + length > data.length)
        throw new Error(`GSPRITE run truncated at byte ${pos}`);
      for (let j = 0; j < length; j++) {
        if (y >= 0 && y < h && x + j >= 0 && x + j < w) {
          pixels[y * w + x + j] = data[pos + j];
          mask[y * w + x + j] = 1;
        }
      }
      pos += length;
    }
    if (!terminated) throw new Error("GSPRITE missing -1 terminator");
    return { type, w, h, pixels, mask };
  }
  throw new Error(`unknown GFX_TYPE ${type}`);
}

// FONT: int height + short charofs[256] + char width[256], glyph rows follow.
export const FONT_HEADER = 4 + 512 + 256;

export function parseFont(data) {
  if (data.length <= FONT_HEADER) throw new Error(`font too small (${data.length} bytes)`);
  const dv = new DataView(data.buffer, data.byteOffset);
  const height = dv.getInt32(0, true);
  if (height < 1 || height > 64) throw new Error(`implausible font height ${height}`);
  const charofs = new Int16Array(256);
  const width = new Uint8Array(256);
  for (let i = 0; i < 256; i++) charofs[i] = dv.getInt16(4 + i * 2, true);
  width.set(data.subarray(516, 772));
  const glyphs = data.subarray(FONT_HEADER);
  for (let i = 0; i < 256; i++)
    if (charofs[i] !== -1 && (charofs[i] < 0 || charofs[i] + width[i] * height > glyphs.length))
      throw new Error(`font glyph ${i} out of bounds (offset ${charofs[i]})`);
  return { height, charofs, width, glyphs };
}

export const FONT_SPACING = 1; // gfxapi.cpp fontspacing

export function strPixelLen(font, str) {
  let len = 0;
  for (let i = 0; i < str.length; i++)
    len += font.width[str.charCodeAt(i) & 0xff] + FONT_SPACING;
  return len;
}

// Light-source corners (gfxapi.h) and shade options.
export const UPPER_LEFT = 0, UPPER_RIGHT = 1, LOWER_LEFT = 2, LOWER_RIGHT = 3;
export const DARK = 0, LIGHT = 1, GREY = 2;

export class Raster {
  constructor(tables) {
    this.buf = new Uint8Array(SCREEN_W * SCREEN_H);
    this.tables = tables; // [dark, light, grey]
  }

  inX(x) { return x >= 0 && x < SCREEN_W; }
  inY(y) { return y >= 0 && y < SCREEN_H; }

  colorBox(x, y, lx, ly, color) {
    if (lx < 1 || ly < 1) return;
    for (let j = 0; j < ly; j++) {
      const py = y + j;
      if (!this.inY(py)) continue;
      for (let i = 0; i < lx; i++) {
        const px = x + i;
        if (this.inX(px)) this.buf[py * SCREEN_W + px] = color & 0xff;
      }
    }
  }

  shadePixel(x, y, table) {
    if (!this.inX(x) || !this.inY(y)) return;
    const p = y * SCREEN_W + x;
    this.buf[p] = table[this.buf[p]];
  }

  hShadeLine(opt, x, y, lx) {
    if (lx < 1) return;
    const t = this.tables[opt];
    for (let i = 0; i < lx; i++) this.shadePixel(x + i, y, t);
  }

  vShadeLine(opt, x, y, ly) {
    if (ly < 1) return;
    const t = this.tables[opt];
    for (let j = 0; j < ly; j++) this.shadePixel(x, y + j, t);
  }

  shadeArea(opt, x, y, lx, ly) {
    const t = this.tables[opt];
    for (let j = 0; j < ly; j++)
      for (let i = 0; i < lx; i++) this.shadePixel(x + i, y + j, t);
  }

  // GFX_ShadeShape: shade only where the pic has opaque/nonzero pixels
  shadeShape(opt, pic, x, y) {
    const t = this.tables[opt];
    for (let j = 0; j < pic.h; j++)
      for (let i = 0; i < pic.w; i++) {
        const opaque = pic.mask ? pic.mask[j * pic.w + i] : pic.pixels[j * pic.w + i];
        if (opaque) this.shadePixel(x + i, y + j, t);
      }
  }

  // GFX_LightBox: rectangle border lit from a corner
  lightBox(opt, x, y, lx, ly) {
    if (lx < 1 || ly < 1) return;
    switch (opt) {
      case UPPER_LEFT:
        this.hShadeLine(LIGHT, x, y, lx - 1);
        this.vShadeLine(LIGHT, x, y + 1, ly - 2);
        this.hShadeLine(DARK, x, y + ly - 1, lx);
        this.vShadeLine(DARK, x + lx - 1, y + 1, ly - 2);
        break;
      case LOWER_LEFT:
        this.hShadeLine(LIGHT, x, y + ly - 1, lx - 1);
        this.vShadeLine(LIGHT, x, y + 1, ly - 2);
        this.hShadeLine(DARK, x, y, lx);
        this.vShadeLine(DARK, x + lx - 1, y + 1, ly - 1);
        break;
      case LOWER_RIGHT:
        this.hShadeLine(LIGHT, x + 1, y, lx - 1);
        this.vShadeLine(LIGHT, x + lx - 1, y + 1, ly - 2);
        this.hShadeLine(DARK, x, y, lx);
        this.vShadeLine(DARK, x, y + 1, ly - 2);
        break;
      case UPPER_RIGHT:
      default:
        this.hShadeLine(LIGHT, x + 1, y, lx - 1);
        this.vShadeLine(LIGHT, x + lx - 1, y + 1, ly - 2);
        this.hShadeLine(DARK, x, y + ly - 1, lx);
        this.vShadeLine(DARK, x, y, ly - 1);
        break;
    }
  }

  vLine(x, y, ly, color) {
    for (let j = 0; j < ly; j++)
      if (this.inX(x) && this.inY(y + j)) this.buf[(y + j) * SCREEN_W + x] = color & 0xff;
  }

  // GFX_PutImage: GPIC block copy (seeThru skips index 0); GSPRITE segments
  putImage(pic, x, y, seeThru) {
    for (let j = 0; j < pic.h; j++)
      for (let i = 0; i < pic.w; i++) {
        const px = x + i, py = y + j;
        if (!this.inX(px) || !this.inY(py)) continue;
        const v = pic.pixels[j * pic.w + i];
        if (pic.mask) { // GSPRITE: only opaque pixels
          if (pic.mask[j * pic.w + i]) this.buf[py * SCREEN_W + px] = v;
        } else if (!seeThru || v) {
          this.buf[py * SCREEN_W + px] = v;
        }
      }
  }

  // GFX_PutTexture: tile the pic across the area
  putTexture(pic, x, y, lx, ly) {
    for (let j = 0; j < ly; j++)
      for (let i = 0; i < lx; i++) {
        const px = x + i, py = y + j;
        if (!this.inX(px) || !this.inY(py)) continue;
        this.buf[py * SCREEN_W + px] = pic.pixels[(j % pic.h) * pic.w + (i % pic.w)];
      }
  }

  // GFX_ScalePic: nearest-neighbour scale into new_lx x new_ly
  scalePic(pic, x, y, newLx, newLy, seeThru) {
    for (let j = 0; j < newLy; j++)
      for (let i = 0; i < newLx; i++) {
        const sx = Math.floor(i * pic.w / newLx);
        const sy = Math.floor(j * pic.h / newLy);
        const px = x + i, py = y + j;
        if (!this.inX(px) || !this.inY(py)) continue;
        const s = sy * pic.w + sx;
        if (pic.mask && !pic.mask[s]) continue;
        const v = pic.pixels[s];
        if (seeThru && !v) continue;
        this.buf[py * SCREEN_W + px] = v;
      }
  }

  // GFX_Print: basecolor is decremented once, glyph bytes are added to it;
  // chars with charofs == -1 are skipped entirely (no advance).
  print(x, y, str, font, basecolor) {
    const color = basecolor - 1;
    for (let k = 0; k < str.length; k++) {
      const ch = str.charCodeAt(k) & 0xff;
      if (font.charofs[ch] === -1) continue;
      const w = font.width[ch];
      const ofs = font.charofs[ch];
      for (let j = 0; j < font.height; j++)
        for (let i = 0; i < w; i++) {
          const v = font.glyphs[ofs + j * w + i];
          if (!v) continue;
          const px = x + i, py = y + j;
          if (this.inX(px) && this.inY(py))
            this.buf[py * SCREEN_W + px] = (color + v) & 0xff;
        }
      x += w + FONT_SPACING;
    }
  }

  toRGBA(rgbPal) {
    const out = new Uint8ClampedArray(SCREEN_W * SCREEN_H * 4);
    for (let i = 0; i < this.buf.length; i++) {
      const [r, g, b] = rgbPal[this.buf[i]];
      out[i * 4] = r; out[i * 4 + 1] = g; out[i * 4 + 2] = b; out[i * 4 + 3] = 255;
    }
    return out;
  }
}


# === src\glb.mjs ===
// GLB container archive (Raptor: Call of the Shadows data files).
// Format from the released game source and the engine port's glbapi.cpp;
// mirrors the Python reference in the Delta Sector installer (raptor_glb.py).
// Browser-portable: Uint8Array/DataView only, no Node APIs.

const KEY = new TextEncoder().encode("32768GLB");
const SEED = 0x19;

export const FAT_ENTRY = 28; // sizeof(KEYFILE)
export const FLAG_ENCODED = 0x1;

export function decrypt(buf) {
  let kidx = SEED % KEY.length;
  let prev = KEY[kidx];
  const out = new Uint8Array(buf.length);
  for (let i = 0; i < buf.length; i++) {
    out[i] = (buf[i] - KEY[kidx] - prev) & 0xff;
    prev = buf[i];
    kidx = (kidx + 1) % KEY.length;
  }
  return out;
}

export function encrypt(buf) {
  let kidx = SEED % KEY.length;
  let prev = KEY[kidx];
  const out = new Uint8Array(buf.length);
  for (let i = 0; i < buf.length; i++) {
    prev = (buf[i] + KEY[kidx] + prev) & 0xff;
    out[i] = prev;
    kidx = (kidx + 1) % KEY.length;
  }
  return out;
}

export function asciiz(bytes) {
  const end = bytes.indexOf(0);
  return new TextDecoder("ascii").decode(end < 0 ? bytes : bytes.subarray(0, end));
}

// -> { items: [{ flags, name, nameRaw, data }] }  (data always decrypted)
export function parseGlb(bytes) {
  if (bytes.length < FAT_ENTRY) throw new Error(`not a GLB file (${bytes.length} bytes)`);
  const hdr = decrypt(bytes.subarray(0, FAT_ENTRY));
  const count = new DataView(hdr.buffer, hdr.byteOffset).getUint32(4, true);
  if (FAT_ENTRY * (count + 1) > bytes.length)
    throw new Error(`not a GLB file (FAT claims ${count} items in ${bytes.length} bytes)`);
  const items = [];
  for (let i = 0; i < count; i++) {
    const e = decrypt(bytes.subarray(FAT_ENTRY * (i + 1), FAT_ENTRY * (i + 2)));
    const dv = new DataView(e.buffer, e.byteOffset);
    const flags = dv.getUint32(0, true);
    const offset = dv.getUint32(4, true);
    const size = dv.getUint32(8, true);
    if (offset < FAT_ENTRY * (count + 1) || offset + size > bytes.length)
      throw new Error(`GLB item ${i} data outside payload area`);
    const nameRaw = e.slice(12, 28);
    let data = bytes.slice(offset, offset + size);
    if (flags & FLAG_ENCODED) data = decrypt(data);
    items.push({ flags, name: asciiz(nameRaw), nameRaw, data });
  }
  return { items };
}

export function buildGlb(items) {
  const count = items.length;
  let offset = FAT_ENTRY * (count + 1);
  const fat = new Uint8Array(FAT_ENTRY * (count + 1));
  const head = new Uint8Array(FAT_ENTRY);
  new DataView(head.buffer).setUint32(4, count, true);
  fat.set(encrypt(head), 0);
  const blobs = [];
  for (let i = 0; i < count; i++) {
    const it = items[i];
    const e = new Uint8Array(FAT_ENTRY);
    const dv = new DataView(e.buffer);
    dv.setUint32(0, it.flags, true);
    dv.setUint32(4, offset, true);
    dv.setUint32(8, it.data.length, true);
    const nameRaw = it.nameRaw ?? new TextEncoder().encode(it.name);
    if (nameRaw.length > 16) throw new Error(`item name too long: ${it.name}`);
    e.set(nameRaw.subarray(0, 16), 12);
    fat.set(encrypt(e), FAT_ENTRY * (i + 1));
    const blob = it.flags & FLAG_ENCODED ? encrypt(it.data) : it.data;
    blobs.push(blob);
    offset += blob.length;
  }
  const total = blobs.reduce((n, b) => n + b.length, fat.length);
  const out = new Uint8Array(total);
  out.set(fat, 0);
  let pos = fat.length;
  for (const b of blobs) {
    out.set(b, pos);
    pos += b.length;
  }
  return out;
}


# === src\glbset.mjs ===
// A set of FILE000n.GLB archives with engine-style item lookup:
// GLB_GetItemID searches files in number order; an item handle is
// (filenum << 16) | index (glbapi.cpp).

import { parseGlb, buildGlb } from "./glb.mjs";

export class GlbSet {
  constructor() {
    this.files = new Map(); // num -> { items }
  }

  add(num, bytes) {
    this.files.set(num, parseGlb(bytes));
  }

  nums() {
    return [...this.files.keys()].sort((a, b) => a - b);
  }

  itemId(name) {
    // GLB_GetItemID refuses empty and space-led names (glbapi.cpp:707)
    if (!name || name[0] === " " || name[0] === "\0") return -1;
    for (const num of this.nums()) {
      const idx = this.files.get(num).items.findIndex(it => it.name === name);
      if (idx >= 0) return (num << 16) | idx;
    }
    return -1;
  }

  byId(id) {
    if (id < 0) return null;
    return this.files.get(id >> 16)?.items[id & 0xffff] ?? null;
  }

  byName(name) {
    return this.byId(this.itemId(name));
  }

  *itemsMatching(re) {
    for (const num of this.nums()) {
      const { items } = this.files.get(num);
      for (let i = 0; i < items.length; i++)
        if (re.test(items[i].name) && items[i].data.length)
          yield { num, index: i, id: (num << 16) | i, item: items[i] };
    }
  }

  build(num) {
    return buildGlb(this.files.get(num).items);
  }
}


# === src\render.mjs ===
// Pixel-faithful port of the engine's window renderer:
//   SWD_PutWin + SWD_ShowAllFields + SWD_PutField + SWD_ShadeButton
// (swdapi.cpp). Deliberate quirks of the original are preserved and marked.

import {
  Raster, parsePic, parseFont, parsePalette, paletteToRgb,
  makeLightTable, makeGreyTable, strPixelLen,
  DARK, LIGHT, GREY, UPPER_RIGHT, LOWER_LEFT, GTYPE_SPRITE, FONT_SPACING,
} from "./gfx.mjs";

// picflag draw styles (gfxapi.h DSTYLE)
const FILL = 0, TEXTURE = 1, PICTURE = 2, SEE_THRU = 3, INVISABLE = 4;
// field types
const FLD_OFF = 0, FLD_TEXT = 1, FLD_BUTTON = 2, FLD_INPUT = 3, FLD_MARK = 4,
  FLD_CLOSE = 5, FLD_DRAGBAR = 6, FLD_BUMPIN = 7, FLD_BUMPOUT = 8, FLD_ICON = 9;
// button status
const NORMAL = 0, UP = 1, DOWN = 2;

// Rendering context bound to a GlbSet: palette, shade tables, caches.
export class RenderContext {
  constructor(glbs) {
    this.glbs = glbs;
    const palItem = glbs.byName("PALETTE_DAT");
    if (!palItem) throw new Error("PALETTE_DAT not found in loaded GLB files");
    this.pal6 = parsePalette(palItem.data);
    this.rgb = paletteToRgb(this.pal6);
    // GFX_MakeLightTable(ltable, 9) / (dtable, -9) / grey (gfxapi.cpp:243)
    this.tables = [makeLightTable(this.pal6, -9), makeLightTable(this.pal6, 9), makeGreyTable(this.pal6)];
    this.picCache = new Map();
    this.fontCache = new Map();
  }

  // Baked item/fontid ints in SWD data are stale; the engine re-resolves
  // them BY NAME at window init (swdapi.cpp:1725,1766,1758) - so do we.
  itemIdFor(rec) {
    return rec.picflag ? this.glbs.itemId(rec.item_name) : -1;
  }

  pic(id) {
    if (id < 0) return null;
    if (!this.picCache.has(id)) {
      const item = this.glbs.byId(id);
      let pic = null;
      // an FLD_TEXT field's item is a text item, not a pic - tolerate anything
      try { if (item && item.data.length >= 20) pic = parsePic(item.data); } catch { /* not a pic */ }
      this.picCache.set(id, pic);
    }
    return this.picCache.get(id);
  }

  font(field) {
    const key = field.font_name;
    if (!this.fontCache.has(key)) {
      const item = this.glbs.byName(field.font_name);
      this.fontCache.set(key, item && item.data.length > 772 ? parseFont(item.data) : null);
    }
    return this.fontCache.get(key);
  }

  newRaster() {
    return new Raster(this.tables);
  }
}

// SWD_ShadeButton. NOTE: the original's UP case has no break and falls
// through into default - preserved here.
function shadeButton(r, opt, x, y, lx, ly) {
  switch (opt) {
    case DOWN:
      r.hShadeLine(DARK, x, y, lx);
      r.vShadeLine(DARK, x + lx - 1, y + 1, ly - 1);
      break;
    case UP:
      r.hShadeLine(LIGHT, x + 2, y, lx - 2);
      r.vShadeLine(LIGHT, x + lx - 1, y + 1, ly - 3);
      // fall through (original has no break)
    default:
      r.hShadeLine(LIGHT, x + 1, y, lx - 1);
      r.vShadeLine(LIGHT, x + lx - 1, y + 1, ly - 2);
      r.hShadeLine(DARK, x, y + ly - 1, lx);
      r.vShadeLine(DARK, x, y, ly - 1);
      break;
  }
}

// SWD_FillText, APPROXIMATE: renders a GLB text item into the field area one
// source line at a time (the original word-wraps to the field width via
// SWD_GetLine). TEXT_COLOR and TEXT_POS commands are honored; TEXT_IMAGE /
// TEXT_RIGHT / TEXT_DOWN are consumed but not rendered. Only FLD_TEXT fields
// that reference a text ITEM take this path - window labels are exact.
function fillText(ctx, r, font, itemId, color, x, y, lx, ly) {
  const item = ctx.glbs.byId(itemId);
  if (!item || !font) return;
  const text = new TextDecoder("ascii").decode(item.data).replace(/\0.*$/s, "");
  let dx = x, dy = y, col = color;
  for (const rawLine of text.split(/\r\n|\n|\r/)) {
    const line = rawLine.trimEnd();
    const m = line.match(/^\s*(TEXT_IMAGE|TEXT_COLOR|TEXT_POS|TEXT_RIGHT|TEXT_DOWN)[\s,;]+(.*)$/);
    if (m) {
      const args = m[2].split(/[\s,;]+/);
      if (m[1] === "TEXT_COLOR") col = parseInt(args[0], 10) || col;
      else if (m[1] === "TEXT_POS") { dx = x + (parseInt(args[0], 10) || 0); dy = y + (parseInt(args[1], 10) || 0); }
      continue;
    }
    if (dy > y + ly - 1) break;
    r.print(dx, dy, line, font, col);
    dy += font.height + 3;
    dx = x;
  }
}

// SWD_PutField
function putField(ctx, r, win, fld) {
  const font = ctx.font(fld);
  const itemId = ctx.itemIdFor(fld);
  const text = fld.textResolved ?? "";
  const fontHeight = font ? font.height : 8;
  const fx = fld.x + win.x;
  const fy = fld.y + win.y;
  let drawText = false;
  let textX = fx + ((fld.lx - (font ? strPixelLen(font, text) : 0)) >> 1);
  let textY = fy + ((fld.ly - fontHeight) >> 1);

  if (fld.bstatus === DOWN && fld.opt !== FLD_DRAGBAR) {
    if (textX > 0) textX--;
    textY++;
  }

  const exitDrawText = () => {
    if (drawText && fld.maxchars > 1 && font) r.print(textX, textY, text, font, fld.fontbasecolor);
  };

  if (fld.picflag && fld.picflag !== INVISABLE) {
    if (itemId === -1) return exitDrawText();
    // Original bug preserved: compares the WINDOW's field count to SEE_THRU(3)
    const drawStyle = win.numflds === SEE_THRU ? 1 : 0;
    const pic = ctx.pic(itemId);

    switch (fld.opt) {
      case FLD_BUTTON:
        if (!pic) break;
        if (fld.picflag === TEXTURE) {
          r.putTexture(pic, fx, fy, fld.lx, fld.ly);
          shadeButton(r, fld.bstatus, fx, fy, fld.lx, fld.ly);
        } else {
          r.putImage(pic, fx, fy, drawStyle);
        }
        drawText = true;
        break;

      case FLD_DRAGBAR:
        if (!pic) break;
        if (fld.picflag === TEXTURE) {
          r.putTexture(pic, fx, fy, fld.lx, fld.ly);
          r.lightBox(UPPER_RIGHT, fx, fy, fld.lx, fld.ly);
        } else {
          r.putImage(pic, fx, fy, drawStyle);
        }
        // inactive-window greying skipped: the editor renders one window
        drawText = true;
        break;

      case FLD_ICON:
        if (!pic) break;
        if (fld.picflag === TEXTURE) {
          r.putTexture(pic, fx, fy, fld.lx, fld.ly);
          return;
        }
        if (fld.lx < pic.w || fld.ly < pic.h) r.scalePic(pic, fx, fy, fld.lx, fld.ly, 0);
        else r.putImage(pic, fx, fy, drawStyle);
        break;

      case FLD_MARK:
      case FLD_CLOSE:
        if (pic) r.putImage(pic, fx, fy, drawStyle);
        break;

      case FLD_TEXT:
        fillText(ctx, r, font, itemId, fld.fontbasecolor, fx, fy, fld.lx, fld.ly);
        break;
    }

    if (!fld.bstatus) return exitDrawText();
  } else {
    switch (fld.opt) {
      case FLD_TEXT:
        if (fld.maxchars && font) r.print(fx, fy, text, font, fld.fontbasecolor);
        break;

      case FLD_BUTTON:
        if (fld.picflag !== INVISABLE) {
          r.colorBox(fx, fy, fld.lx, fld.ly, fld.color);
          shadeButton(r, fld.bstatus, fx, fy, fld.lx, fld.ly);
          drawText = true;
        } else if (font) {
          r.print(textX, textY, text, font, fld.fontbasecolor);
        }
        break;

      case FLD_INPUT:
        r.colorBox(fx, fy, fld.lx, fld.ly, fld.bstatus === NORMAL ? fld.color : fld.lite);
        if (fld.maxchars && font) r.print(fx + 1, textY, text, font, fld.fontbasecolor);
        if (fld.bstatus && font) {
          const caretX = fx + 1 + strPixelLen(font, text);
          if (strPixelLen(font, text) + 2 < fld.lx)
            r.vLine(caretX, fy + 1, fontHeight - 1, fld.fontbasecolor);
        }
        break;

      case FLD_MARK:
        r.colorBox(fx, fy, fld.lx, fld.ly, fld.color);
        r.lightBox(UPPER_RIGHT, fx, fy, fld.lx, fld.ly);
        r.colorBox(fx + 2, fy + 2, fld.lx - 4, fld.ly - 4, 0);
        textX = fx + 3; textY = fy + 3;
        if (fld.mark) {
          r.colorBox(fx + 3, fy + 3, fld.lx - 6, fld.ly - 6, fld.lite);
          shadeButton(r, fld.bstatus, fx + 3, fy + 3, fld.lx - 6, fld.ly - 6);
        } else {
          r.colorBox(fx + 3, fy + 3, fld.lx - 6, fld.ly - 6, 0);
        }
        break;

      case FLD_CLOSE:
        if (fld.picflag === INVISABLE) return exitDrawText();
        r.colorBox(fx, fy, fld.lx, fld.ly, fld.lite);
        r.lightBox(UPPER_RIGHT, fx, fy, fld.lx, fld.ly);
        r.colorBox(fx + 2, fy + 2, fld.lx - 4, fld.ly - 4, fld.lite);
        r.colorBox(fx + 3, fy + 3, fld.lx - 6, fld.ly - 6, fld.lite);
        shadeButton(r, fld.bstatus, fx + 3, fy + 3, fld.lx - 6, fld.ly - 6);
        textX = fx + 3; textY = fy + 3;
        break;

      case FLD_DRAGBAR:
        if (fld.picflag !== INVISABLE) r.colorBox(fx, fy, fld.lx, fld.ly, fld.color);
        if (fld.maxchars > 1 && font) r.print(textX, textY, text, font, fld.fontbasecolor);
        // inactive-window greying skipped (single-window editor)
        break;

      case FLD_BUMPIN:
        if (fld.color) r.shadeArea(DARK, fx + 1, fy, fld.lx - 1, fld.ly - 1);
        r.lightBox(LOWER_LEFT, fx, fy, fld.lx, fld.ly);
        if (!fld.color) r.colorBox(fx + 1, fy + 1, fld.lx - 2, fld.ly - 2, 0);
        break;

      case FLD_BUMPOUT:
        r.shadeArea(LIGHT, fx + 1, fy, fld.lx - 1, fld.ly - 1);
        r.lightBox(UPPER_RIGHT, fx, fy, fld.lx, fld.ly);
        if (!fld.color) r.colorBox(fx + 1, fy + 1, fld.lx - 2, fld.ly - 2, 0);
        break;
    }
  }

  if (fld.bstatus && fld.opt !== FLD_INPUT) {
    const h = fld.picflag === PICTURE ? ctx.pic(itemId) : null;
    const opt = fld.bstatus === DOWN ? DARK : LIGHT;
    if (h && h.type === GTYPE_SPRITE) r.shadeShape(opt, h, fx, fy);
    else r.shadeArea(opt, fx, fy, fld.lx, fld.ly);
  }

  exitDrawText();
}

// SWD_ShowAllFields: field drop shadows, then each field
function showAllFields(ctx, r, swd) {
  const win = swd.header;
  for (const fld of swd.fields) {
    if (fld.opt === FLD_OFF) continue;
    const fx = win.x + fld.x;
    const fy = win.y + fld.y;
    if (fld.shadow) {
      if (fld.picflag !== SEE_THRU) {
        r.lightBox(UPPER_RIGHT, fx - 1, fy + 1, fld.lx, fld.ly);
      } else {
        const shadowItem = ctx.itemIdFor(fld);
        if (shadowItem !== -1) {
          const pic = ctx.pic(shadowItem);
          if (pic) r.shadeShape(DARK, pic, fx - 1, fy + 1);
        }
      }
    }
    putField(ctx, r, win, fld);
  }
}

// SWD_PutWin: window shadow, background, then fields.
// Returns the raster (fresh unless one is passed in).
export function drawWindow(ctx, swd, raster = null, clearColor = 0) {
  const r = raster ?? ctx.newRaster();
  if (!raster) r.buf.fill(clearColor);
  const w = swd.header;
  const wItem = ctx.itemIdFor(w);
  const x = w.x - 8;
  const y = w.y + 8;
  const y2 = w.y + w.ly;

  if (w.shadow) {
    if (w.picflag === SEE_THRU && wItem !== -1) {
      const pic = ctx.pic(wItem);
      if (pic) r.shadeShape(DARK, pic, x, y);
    } else {
      r.shadeArea(DARK, x, y, 8, w.ly - 8);
      r.shadeArea(DARK, x, y2, w.lx, 8);
    }
  }

  switch (w.picflag) {
    case FILL:
      r.colorBox(w.x, w.y, w.lx, w.ly, w.color);
      if (w.lx < 320 && w.ly < 200) r.lightBox(UPPER_RIGHT, w.x, w.y, w.lx, w.ly);
      break;
    case PICTURE:
      if (wItem !== -1) { const p = ctx.pic(wItem); if (p) r.putImage(p, w.x, w.y, 0); }
      break;
    case SEE_THRU:
      if (wItem !== -1) { const p = ctx.pic(wItem); if (p) r.putImage(p, w.x, w.y, 1); }
      break;
    case TEXTURE:
      if (wItem !== -1) {
        const p = ctx.pic(wItem);
        if (p) {
          r.putTexture(p, w.x, w.y, w.lx, w.ly);
          r.lightBox(UPPER_RIGHT, w.x, w.y, w.lx, w.ly);
        }
      }
      break;
    case INVISABLE:
      if (w.color === 0) {
        r.shadeArea(DARK, w.x, w.y, w.lx, w.ly);
        r.lightBox(UPPER_RIGHT, w.x, w.y, w.lx, w.ly);
      }
      break;
  }

  if (swd.fields.length) showAllFields(ctx, r, swd);
  return r;
}


# === src\swd.mjs ===
// SWD window resources - the file format of Scott Host's original window
// maker tool, as consumed by the engine's swdapi.cpp.
//
// On-disk layout (all ints little-endian signed 32-bit):
//   SWIN header        120 bytes
//   (optional gap)     bytes between 120 and header.fldofs, unused
//   SFIELD32 records   148 bytes x header.numflds, at header.fldofs
//   text area          everything after the last field record
//
// Each field's txtoff is relative to ITS OWN record start
// (swdapi.cpp:329  fld_text = (char*)curfld + curfld->txtoff).
//
// Parsing keeps every byte (raw name arrays, header gap, full text blob), so
// serializeSwd(parseSwd(b)) is byte-identical - the round-trip suite enforces
// this over every *_SWD item in the shipped game.

import { asciiz } from "./glb.mjs";

export const SWIN_SIZE = 120;
export const SFIELD32_SIZE = 148;

export const FIELD_TYPES = [
  "off", "text", "button", "input", "mark", "close",
  "dragbar", "bumpin", "bumpout", "icon", "objarea", "viewarea",
];

export const DRAW_STYLES = ["fill", "texture", "picture", "see_thru", "invisible"];

const SWIN_INTS = [
  ["version", 0], ["swdsize", 4], ["arrowflag", 8], ["display", 12],
  ["opt3", 16], ["opt4", 20], ["id", 24], ["type", 28],
  // name[16] @32, item_name[16] @48
  ["item", 64], ["picflag", 68], ["lock", 72], ["fldofs", 76],
  ["txtofs", 80], ["firstfld", 84], ["opt", 88], ["color", 92],
  ["numflds", 96], ["x", 100], ["y", 104], ["lx", 108],
  ["ly", 112], ["shadow", 116],
];

const SFIELD_INTS = [
  ["opt", 0], ["id", 4], ["hotkey", 8], ["kbflag", 12],
  ["opt3", 16], ["opt4", 20], ["input_opt", 24], ["bstatus", 28],
  // name[16] @32, item_name[16] @48
  ["item", 64],
  // font_name[16] @68
  ["fontid", 84], ["fontbasecolor", 88], ["maxchars", 92], ["picflag", 96],
  ["color", 100], ["lite", 104], ["mark", 108], ["saveflag", 112],
  ["shadow", 116], ["selectable", 120], ["x", 124], ["y", 128],
  ["lx", 132], ["ly", 136], ["txtoff", 140], ["placeholder", 144],
];

function readStruct(bytes, base, ints, names) {
  const dv = new DataView(bytes.buffer, bytes.byteOffset + base);
  const out = {};
  for (const [key, off] of ints) out[key] = dv.getInt32(off, true);
  for (const [key, off] of names) {
    out[`${key}Raw`] = bytes.slice(base + off, base + off + 16);
    out[key] = asciiz(out[`${key}Raw`]);
  }
  return out;
}

function writeStruct(bytes, base, obj, ints, names) {
  const dv = new DataView(bytes.buffer, bytes.byteOffset + base);
  for (const [key, off] of ints) dv.setInt32(off, obj[key], true);
  for (const [key, off] of names) bytes.set(obj[`${key}Raw`], base + off);
}

const SWIN_NAMES = [["name", 32], ["item_name", 48]];
const SFIELD_NAMES = [["name", 32], ["item_name", 48], ["font_name", 68]];

// -> { header, headerGap, fields, text }
// fields[i].textResolved is the NUL-terminated string its txtoff points at
// (informational; serialization uses the raw text blob).
export function parseSwd(bytes) {
  if (bytes.length < SWIN_SIZE) throw new Error(`SWD too small: ${bytes.length}`);
  const header = readStruct(bytes, 0, SWIN_INTS, SWIN_NAMES);
  const { fldofs, numflds } = header;
  if (numflds < 0 || fldofs < SWIN_SIZE || fldofs + numflds * SFIELD32_SIZE > bytes.length)
    throw new Error(`bad field table: fldofs=${fldofs} numflds=${numflds} len=${bytes.length}`);
  const headerGap = bytes.slice(SWIN_SIZE, fldofs);
  const fields = [];
  for (let i = 0; i < numflds; i++) {
    const base = fldofs + i * SFIELD32_SIZE;
    const f = readStruct(bytes, base, SFIELD_INTS, SFIELD_NAMES);
    f.typeName = FIELD_TYPES[f.opt] ?? `unknown(${f.opt})`;
    const tp = base + f.txtoff;
    // require the string to be NUL-terminated inside the resource
    f.textResolved = tp >= 0 && tp < bytes.length && bytes.indexOf(0, tp) !== -1
      ? asciiz(bytes.subarray(tp)) : null;
    fields.push(f);
  }
  const text = bytes.slice(fldofs + numflds * SFIELD32_SIZE);
  return { header, headerGap, fields, text };
}

export function serializeSwd(swd) {
  const { header, headerGap, fields, text } = swd;
  const fldofs = SWIN_SIZE + headerGap.length;
  const out = new Uint8Array(fldofs + fields.length * SFIELD32_SIZE + text.length);
  writeStruct(out, 0, { ...header, fldofs, numflds: fields.length }, SWIN_INTS, SWIN_NAMES);
  out.set(headerGap, SWIN_SIZE);
  fields.forEach((f, i) => writeStruct(out, fldofs + i * SFIELD32_SIZE, f, SFIELD_INTS, SFIELD_NAMES));
  out.set(text, fldofs + fields.length * SFIELD32_SIZE);
  return out;
}


# === tests\bundle.test.mjs ===
// Bundler smoke test: build the single-file dist into a temp dir, prove the
// bundled script parses as a module with no surviving import/export
// statements, and EXECUTE the library portion (everything before the app
// marker, which needs a DOM) to catch initialization-order failures.

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync, rmSync, mkdtempSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

test("dist bundle builds, parses, and its library code executes", () => {
  const distDir = mkdtempSync(join(tmpdir(), "wm-dist-"));
  try {
    execFileSync(process.execPath, [join(ROOT, "build.mjs")], {
      stdio: "pipe", env: { ...process.env, WM_DIST_DIR: distDir },
    });
    const html = readFileSync(join(distDir, "raptor-window-maker.html"), "utf8");
    const m = html.match(/<script type="module">([\s\S]*?)<\/script>/);
    assert.ok(m, "no module script block in dist html");
    const script = m[1];
    assert.ok(!/^\s*import\b/m.test(script), "import statement survived bundling");
    assert.ok(!/^\s*export\b/m.test(script), "export statement survived bundling");

    // full-script syntax check
    const full = join(distDir, "bundle-full.mjs");
    writeFileSync(full, script);
    execFileSync(process.execPath, ["--check", full], { stdio: "pipe" });

    // execute the library portion + a real parse/serialize round-trip
    const marker = script.indexOf("// ==== app ====");
    assert.ok(marker > 0, "app marker missing from bundle");
    const lib = script.slice(0, marker) + `
      const w = newWindow({ name: "SMOKE_SWD" });
      addField(w, { name: "OK", label: "OK" });
      const re = parseSwd(serializeSwd(w));
      if (re.fields[0].textResolved !== "OK") throw new Error("bundle round-trip broken");
      console.log("bundle-lib-ok");
    `;
    const libFile = join(distDir, "bundle-lib.mjs");
    writeFileSync(libFile, lib);
    const out = execFileSync(process.execPath, [libFile], { stdio: "pipe" }).toString();
    assert.match(out, /bundle-lib-ok/);
  } finally {
    rmSync(distDir, { recursive: true, force: true });
  }
});


# === tests\edit.test.mjs ===
// Edit-operation tests. The crown jewel is installer parity: applying our
// edit ops to the pristine SHIPCOMP_SWD must reproduce, byte for byte, the
// window that the Delta Sector installer produces with its hand-rolled
// binary patch. That pins the ops to a known-good real-world artifact.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { parseGlb } from "../src/glb.mjs";
import { parseSwd, serializeSwd } from "../src/swd.mjs";
import { setLabel, addField, deleteField, setProps, compactText, newWindow } from "../src/edit.mjs";
import { pristineDir, patchedDir } from "./helpers.mjs";

const PRISTINE = pristineDir();
const PATCHED = patchedDir();

function shipcomp(dir) {
  const { items } = parseGlb(new Uint8Array(readFileSync(join(dir, existsSync(join(dir, "FILE0001.GLB")) ? "FILE0001.GLB" : "file0001.glb"))));
  return items.find(it => it.name === "SHIPCOMP_SWD").data;
}

const haveData = !!(PRISTINE && PATCHED);

test("edit ops reproduce the Delta installer's SHIPCOMP patch byte-for-byte", { skip: !haveData && "needs RAPTOR_DIR (pristine) and RAPTOR_PATCHED_DIR (Delta-patched)" }, () => {
  const swd = parseSwd(shipcomp(PRISTINE));
  assert.equal(swd.fields.length, 12);

  // what install_delta_sector.py patch_shipcomp() does, expressed as ops
  addField(swd, { cloneFrom: 10, name: "GAME4", label: "DELTA SECTOR" });
  for (const [idx, y] of [[4, 39], [5, 61], [10, 83], [12, 105], [11, 127]])
    setProps(swd.fields[idx], { y });

  const expected = shipcomp(PATCHED);
  assert.deepEqual(Buffer.from(serializeSwd(swd)), Buffer.from(expected));
});

test("setLabel repoints text and survives round-trip", { skip: !haveData && "needs RAPTOR_DIR (pristine) and RAPTOR_PATCHED_DIR (Delta-patched)" }, () => {
  const swd = parseSwd(shipcomp(PRISTINE));
  setLabel(swd, 4, "ALPHA SECTOR");
  const re = parseSwd(serializeSwd(swd));
  assert.equal(re.fields[4].textResolved, "ALPHA SECTOR");
  // every other label untouched
  const orig = parseSwd(shipcomp(PRISTINE));
  re.fields.forEach((f, i) => {
    if (i !== 4) assert.equal(f.textResolved, orig.fields[i].textResolved);
  });
});

test("deleteField keeps remaining labels resolvable", { skip: !haveData && "needs RAPTOR_DIR (pristine) and RAPTOR_PATCHED_DIR (Delta-patched)" }, () => {
  const swd = parseSwd(shipcomp(PRISTINE));
  const labels = swd.fields.map(f => f.textResolved);
  deleteField(swd, 5);
  const re = parseSwd(serializeSwd(swd));
  assert.equal(re.fields.length, 11);
  const expect = [...labels.slice(0, 5), ...labels.slice(6)];
  assert.deepEqual(re.fields.map(f => f.textResolved), expect);
});

test("compactText drops dead bytes but keeps labels", { skip: !haveData && "needs RAPTOR_DIR (pristine) and RAPTOR_PATCHED_DIR (Delta-patched)" }, () => {
  const swd = parseSwd(shipcomp(PRISTINE));
  const labels = swd.fields.map(f => f.textResolved);
  setLabel(swd, 0, "X"); // leaves the old label as dead bytes
  setLabel(swd, 0, labels[0]); // and another
  const before = serializeSwd(swd).length;
  compactText(swd);
  const after = serializeSwd(swd).length;
  assert.ok(after < before, `compact did not shrink (${before} -> ${after})`);
  const re = parseSwd(serializeSwd(swd));
  assert.deepEqual(re.fields.map(f => f.textResolved), labels);
});

test("newWindow + addField produces a parseable window from nothing", () => {
  const swd = newWindow({ name: "TEST_SWD", lx: 160, ly: 90 });
  addField(swd, { name: "OK", label: "OK", x: 20, y: 60, lx: 60, ly: 16 });
  addField(swd, { cloneFrom: 0, name: "CANCEL", label: "CANCEL", x: 90 });
  const re = parseSwd(serializeSwd(swd));
  assert.equal(re.header.name, "TEST_SWD");
  assert.deepEqual(re.fields.map(f => f.textResolved), ["OK", "CANCEL"]);
  assert.equal(re.fields[1].x, 90);
  assert.equal(re.fields[1].y, 60); // cloned from field 0
});


# === tests\glbexport.test.mjs ===
// GLB rebuild / export integrity. buildGlb() re-packs the archive (fresh
// offsets, zeroed header padding), so byte-identity with the original file
// is not the contract - LOGICAL identity is: every item keeps its name,
// flags, order and exact decrypted payload, and a rebuilt archive re-parses
// to the same thing. Patching one SWD must leave every other item intact.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { parseGlb, buildGlb } from "../src/glb.mjs";
import { parseSwd, serializeSwd } from "../src/swd.mjs";
import { setLabel } from "../src/edit.mjs";
import { pristineDir, glbNames } from "./helpers.mjs";

const dir = pristineDir();

function logicalEqual(a, b, label) {
  assert.equal(a.items.length, b.items.length, `${label}: item count`);
  for (let i = 0; i < a.items.length; i++) {
    assert.equal(a.items[i].name, b.items[i].name, `${label}: item ${i} name`);
    assert.equal(a.items[i].flags, b.items[i].flags, `${label}: item ${i} flags`);
    assert.deepEqual(Buffer.from(a.items[i].data), Buffer.from(b.items[i].data),
      `${label}: item ${i} (${a.items[i].name}) payload`);
  }
}

test("untouched archives rebuild to logically identical archives", { skip: !dir && "no game data found (set RAPTOR_DIR)" }, () => {
  for (const name of glbNames(dir)) {
    const original = parseGlb(new Uint8Array(readFileSync(join(dir, name))));
    const rebuilt = parseGlb(buildGlb(original.items));
    logicalEqual(original, rebuilt, name);
  }
});

test("patching one SWD leaves every other item byte-identical", { skip: !dir && "no game data found (set RAPTOR_DIR)" }, () => {
  const name = glbNames(dir).find(n => /0001/.test(n));
  const original = parseGlb(new Uint8Array(readFileSync(join(dir, name))));
  const edited = parseGlb(new Uint8Array(readFileSync(join(dir, name))));
  const idx = edited.items.findIndex(it => it.name === "SHIPCOMP_SWD");
  const swd = parseSwd(edited.items[idx].data);
  setLabel(swd, 4, "PARITY TEST");
  edited.items[idx].data = serializeSwd(swd);

  const rebuilt = parseGlb(buildGlb(edited.items));
  assert.equal(rebuilt.items.length, original.items.length);
  for (let i = 0; i < rebuilt.items.length; i++) {
    if (i === idx) {
      const re = parseSwd(rebuilt.items[i].data);
      assert.equal(re.fields[4].textResolved, "PARITY TEST");
    } else {
      assert.deepEqual(Buffer.from(rebuilt.items[i].data), Buffer.from(original.items[i].data),
        `item ${i} (${original.items[i].name}) changed`);
    }
  }
});


# === tests\helpers.mjs ===
// Shared test helpers: locate game data (env-configurable, skip-friendly)
// and load GLB sets. No game data ships with the repo; suites that need it
// skip when none is found.
//
//   RAPTOR_DIR          pristine v1.2 full-game folder (FILE000n.GLB)
//   RAPTOR_PATCHED_DIR  a Delta-Sector-patched copy (installer parity test)
//   RAPTOR_DIRS         extra folders for the round-trip sweep (";"-separated)

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { GlbSet } from "../src/glbset.mjs";

const DEFAULT_PRISTINE =
  "F:\\SteamLibrary\\steamapps\\common\\Raptor Call of the Shadows\\Raptor - Call of the Shadows";
const DEFAULT_PATCHED = "I:\\Projects\\Raptor-Decomp\\playtest-s4";

function firstExisting(...candidates) {
  return candidates.find(d => d && existsSync(d)) ?? null;
}

export function pristineDir() {
  return firstExisting(process.env.RAPTOR_DIR, DEFAULT_PRISTINE);
}

export function patchedDir() {
  return firstExisting(process.env.RAPTOR_PATCHED_DIR, DEFAULT_PATCHED);
}

export function sweepDirs() {
  const extra = process.env.RAPTOR_DIRS?.split(";") ?? [];
  const all = [...extra, pristineDir(), patchedDir()].filter(Boolean);
  return [...new Set(all)].filter(d => existsSync(d));
}

export function glbNames(dir) {
  return readdirSync(dir).filter(n => /^file\d{4}\.glb$/i.test(n)).sort();
}

export function loadSet(dir) {
  const glbs = new GlbSet();
  for (const n of glbNames(dir)) {
    const m = n.match(/^file(\d{4})\.glb$/i);
    glbs.add(parseInt(m[1], 10), new Uint8Array(readFileSync(join(dir, n))));
  }
  return glbs;
}


# === tests\render.test.mjs ===
// Renders every shipped window through the ported engine drawing code.
// Framebuffer hashes are pinned whenever the loaded data IS the pristine
// v1.2 SWD content (checked by fingerprint, not by where the path came
// from); any other data gets the smoke assertions and reported hashes.

import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { parseSwd } from "../src/swd.mjs";
import { RenderContext, drawWindow } from "../src/render.mjs";
import { pristineDir, loadSet } from "./helpers.mjs";

// sha256(name+bytes of every SWD item)[0:16], pristine v1.2 full game
const V12_FINGERPRINT = "da255cf36c873749";

function swdFingerprint(glbs) {
  const h = createHash("sha256");
  for (const { item } of glbs.itemsMatching(/_SWD$/)) {
    h.update(item.name);
    h.update(item.data);
  }
  return h.digest("hex").slice(0, 16);
}

// sha256(framebuffer)[0:12] per window, pristine v1.2 full-game data
const PINNED = {
  STORE_SWD: "09303549d89b",
  MAIN_SWD: "b4bbbd94194a",
  SHIPCOMP_SWD: "b101f3348103",
  HANGAR_SWD: "620744b12cae",
  ASK_SWD: "04cd117272cf",
  LOCKER_SWD: "4f7988030a00",
  REGISTER_SWD: "1271e5eb4bc4",
  HELP_SWD: "5d86a14fd6bb",
  LOAD_SWD: "bf2357916eb2",
  MSG_SWD: "d03a7cf5f5cd",
  ORDER_SWD: "680654fe88c6",
  CREDIT_SWD: "d6ef0ec5663e",
  ASKDIFF_SWD: "2ce77ece067e",
  WINGAME_SWD: "68b051f37164",
  OPTS_SWD: "5b3f01969a94",
  LOADCOMP_SWD: "2a7ff85c38c0",
};

const dir = pristineDir();

test("all shipped windows render, pinned to known framebuffer hashes", { skip: !dir && "no game data found (set RAPTOR_DIR)" }, () => {
  const glbs = loadSet(dir);
  const ctx = new RenderContext(glbs);
  const pristine = swdFingerprint(glbs) === V12_FINGERPRINT;
  if (!pristine) console.log("data is not pristine v1.2 - hash pinning off, smoke checks only");
  let count = 0;
  for (const { item } of glbs.itemsMatching(/_SWD$/)) {
    const swd = parseSwd(item.data);
    const r = drawWindow(ctx, swd);
    const colors = new Set(r.buf);
    // LOCKER_SWD legitimately renders blank: its background art is absent
    // from v1.2 data and its content is drawn by game code into viewareas.
    if (item.name !== "LOCKER_SWD")
      assert.ok(colors.size > 2, `${item.name}: only ${colors.size} distinct colors`);
    const hash = createHash("sha256").update(r.buf).digest("hex").slice(0, 12);
    console.log(`${item.name.padEnd(16)} ${swd.fields.length.toString().padStart(2)} fields  ${colors.size.toString().padStart(3)} colors  ${hash}`);
    if (pristine && PINNED[item.name])
      assert.equal(hash, PINNED[item.name], `${item.name}: rendering changed`);
    count++;
  }
  if (pristine) assert.equal(count, 16);
});


# === tests\roundtrip.test.mjs ===
// Byte-exact round-trip of every SWD window resource in the shipped game.
// Game-data location and skip behavior: see helpers.mjs.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { parseGlb } from "../src/glb.mjs";
import { parseSwd, serializeSwd } from "../src/swd.mjs";
import { sweepDirs, glbNames } from "./helpers.mjs";

const dirs = sweepDirs();

function* swdItems(dir) {
  for (const glbName of glbNames(dir)) {
    const { items } = parseGlb(new Uint8Array(readFileSync(join(dir, glbName))));
    for (const item of items)
      if (item.name.endsWith("_SWD") && item.data.length) yield { glbName, item };
  }
}

test("every shipped SWD item round-trips byte-identically", { skip: dirs.length === 0 && "no game data found (set RAPTOR_DIR)" }, () => {
  let total = 0;
  const typeCounts = {};
  for (const dir of dirs) {
    let found = 0;
    for (const { glbName, item } of swdItems(dir)) {
      const swd = parseSwd(item.data);
      const rebuilt = serializeSwd(swd);
      assert.deepEqual(
        Buffer.from(rebuilt), Buffer.from(item.data),
        `${dir} ${glbName} ${item.name}: round-trip differs`,
      );
      assert.equal(swd.header.numflds, swd.fields.length);
      for (const f of swd.fields) {
        typeCounts[f.typeName] = (typeCounts[f.typeName] ?? 0) + 1;
        assert.ok(f.typeName !== undefined && !f.typeName.startsWith("unknown"),
          `${item.name}: unknown field type ${f.opt}`);
        assert.ok(f.textResolved !== null, `${item.name}: field ${f.id} text out of bounds`);
      }
      found++;
    }
    assert.ok(found > 0, `no SWD items under ${dir}`);
    console.log(`${dir}: ${found} SWD windows OK`);
    total += found;
  }
  console.log("field types:", JSON.stringify(typeCounts));
  // the full game ships 16 windows per copy
  assert.ok(total >= 16, `suspiciously few SWD items (${total})`);
});

test("SHIPCOMP_SWD parses with known field counts", { skip: dirs.length === 0 && "no game data found (set RAPTOR_DIR)" }, () => {
  for (const dir of dirs) {
    for (const { item } of swdItems(dir)) {
      if (item.name !== "SHIPCOMP_SWD") continue;
      const swd = parseSwd(item.data);
      // 12 fields as shipped; 13 once the Delta Sector installer added GAME4
      assert.ok([12, 13].includes(swd.fields.length), `${dir}: ${swd.fields.length} fields`);
      const labels = swd.fields.map(f => f.textResolved);
      assert.ok(labels.includes("BRAVO SECTOR") && labels.includes("TANGO SECTOR"),
        `${dir}: sector labels missing in ${JSON.stringify(labels)}`);
      if (swd.fields.length === 13)
        assert.ok(swd.fields.some(f => f.name === "GAME4" && f.textResolved === "DELTA SECTOR"),
          `${dir}: patched window lacks GAME4/DELTA SECTOR`);
    }
  }
});

test("synthetic window survives parse/serialize without game data", () => {
  const enc = new TextEncoder();
  const text = enc.encode("HELLO\0");
  const bytes = new Uint8Array(120 + 148 + text.length);
  const dv = new DataView(bytes.buffer);
  dv.setInt32(76, 120, true);            // fldofs
  dv.setInt32(96, 1, true);              // numflds
  dv.setInt32(108, 320, true);           // lx
  dv.setInt32(112, 200, true);           // ly
  bytes.set(enc.encode("TESTWIN"), 32);
  dv.setInt32(120 + 0, 2, true);         // field opt = button
  dv.setInt32(120 + 4, 7, true);         // field id
  bytes.set(enc.encode("BTN"), 120 + 32);
  dv.setInt32(120 + 140, 148, true);     // txtoff -> text right after this record
  bytes.set(text, 268);
  const swd = parseSwd(bytes);
  assert.equal(swd.header.name, "TESTWIN");
  assert.equal(swd.fields.length, 1);
  assert.equal(swd.fields[0].typeName, "button");
  assert.equal(swd.fields[0].textResolved, "HELLO");
  assert.deepEqual(Buffer.from(serializeSwd(swd)), Buffer.from(bytes));
});

test("malformed inputs are rejected, not crashed on", () => {
  assert.throws(() => parseGlb(new Uint8Array(4)), /not a GLB/);
  assert.throws(() => parseGlb(new Uint8Array(64)), /not a GLB|past end/);
  assert.throws(() => parseSwd(new Uint8Array(10)), /too small/);
  const neg = new Uint8Array(300);
  const dv = new DataView(neg.buffer);
  dv.setInt32(76, 120, true);
  dv.setInt32(96, -5, true); // negative numflds
  assert.throws(() => parseSwd(neg), /bad field table/);
});
